    "explanation": "アンモニアの結合の種類を問う。正解はウ（共有結合・電気陰性度・水素結合）。\n\n(a) N と H は互いの不対電子を出し合って共有結合をつくる。配位結合は NH₃ の非共有電子対を H⁺ に与えて NH₄⁺ になるときの結合で、分子内の N–H そのものではない。\n(b) N は電気陰性度が大きく、N–H の共有電子対を強く引きつけるので分子が極性をもつ。\n(c) 電気陰性度の大きい原子（F・O・N）に結合した H が、隣の分子の F・O・N と引き合う結合が水素結合。NH₃ の沸点が同族の PH₃ より高い理由でもある。\n\n「共有結合（分子内）→ 電気陰性度の差（極性）→ 水素結合（分子間）」の流れ。ファンデルワールス力はすべての分子にはたらく弱い力で、N が「有する」ものではない。",
