    "stem": "K⁺、Ag⁺、Fe³⁺、Cu²⁺ の 4 種類の金属イオンを含む混合溶液に下記①〜④の操作を行った。\n\n① 希塩酸を加え、生じた「沈殿物 A」をろ過により分離し、「ろ液 X」を得た。\n② 次に、硫化水素を十分に通じ、生じた「沈殿物 B」をろ過により分離し、「ろ液 Y」を得た。\n③ 「ろ液 Y」を加熱した後、希硝酸を加えた。\n④ その後、過剰のアンモニア水を加え、生じた「沈殿物 C」をろ過により分離し、「ろ液 Z」を得た。",
    "question": "①〜④の操作で回収される「ろ液 X〜Z」について誤った文章はどれか。一つ選べ。",
    "choices": [
      "「ろ液 X」に、過剰のアンモニア水を加えると錯イオンが形成される。",
      "アの操作では、「沈殿物 C」と同じ沈殿物が生じる。",
      "「ろ液 Y」には、3 価の金属イオンが含まれる。",
      "「ろ液 Y」の加熱操作は、溶液中の硫化水素を除くために行う。",
      "「ろ液 Z」の炎色反応は、赤紫色を呈する。"
    ],
    "answer": 2,
    "explanation": "各段階のろ液に残っているイオンを追う問題。誤りはウ。\n\n同定：ろ液 X には Fe³⁺・Cu²⁺・K⁺、ろ液 Y には Fe²⁺・K⁺（H₂S が Fe³⁺ を Fe²⁺ に還元する）、ろ液 Z には K⁺。\n\nア：正しい。ろ液 X の Cu²⁺ は過剰のアンモニア水で深青色の [Cu(NH₃)₄]²⁺ になる。\nイ：正しい。同じ操作で Fe³⁺ は Fe(OH)₃（沈殿物 C と同じ）として沈殿する。Fe(OH)₃ は過剰のアンモニア水に溶けない。\nウ：誤り。H₂S は還元剤なので、ろ液 Y の鉄は 2 価の Fe²⁺ になっている。3 価の金属イオンは含まれない。\nエ：正しい。溶けている H₂S を加熱で追い出してから、希硝酸で Fe²⁺ を Fe³⁺ に酸化する。\nオ：正しい。ろ液 Z に残る K⁺ の炎色反応は赤紫色。\n\n「H₂S を通した後は Fe³⁺ が Fe²⁺ になっている」ので、加熱（H₂S 除去）→ 希硝酸（再酸化）の操作が必要になる。",
    "choiceNotes": [
      "誤り（この記述は正しい）。Cu²⁺ が [Cu(NH₃)₄]²⁺ になる。",
      "誤り（この記述は正しい）。ろ液 X の Fe³⁺ がアンモニア水で Fe(OH)₃ になり、沈殿物 C と同じ。",
      "正解。H₂S によって Fe³⁺ は Fe²⁺ に還元されているので、ろ液 Y に 3 価のイオンはない。",
      "誤り（この記述は正しい）。残った H₂S を除かないと、次に加える希硝酸が H₂S の酸化に使われてしまう。",
      "誤り（この記述は正しい）。K の炎色反応は赤紫色。"
    ]
