    "explanation": "有機化合物の元素分析（リービッヒ法）の装置の各部の役割を問う問題。正解は⑤（オ）。\n\n試料を乾いた酸素の中で燃焼させると、炭素は二酸化炭素 CO₂、水素は水 H₂O になる。しかし燃焼が不完全だと一酸化炭素 CO や炭素の粒（すす）が生じ、C の質量を正しく求められない。そこで燃焼ガスを加熱した酸化銅(II) CuO の上に通し、CO や炭素を CO₂ まで完全に酸化する（CuO ＋ CO → Cu ＋ CO₂）。つまり X は酸化銅(II)で、役割は酸化剤である。黒色の CuO が反応後に赤色の Cu になることからも、CuO が酸素を与えて還元されている（＝酸化剤として働いている）ことがわかる。\n\nそのあとのガラス管 Ⅰ には塩化カルシウム CaCl₂ を入れて水 H₂O を吸収させ、ガラス管 Ⅱ にはソーダ石灰（NaOH と CaO）を入れて CO₂ を吸収させる。順序が重要で、ソーダ石灰は CO₂ だけでなく水も吸収するため、先に CaCl₂ で水を除いてからでないと、Ⅱ の増加量が CO₂ だけの質量にならない。逆にすると CO₂ と水が両方ソーダ石灰に吸収されてしまい、分けて測れない。\n\n「CuO は酸化剤（完全燃焼させるため）、CaCl₂ は水、ソーダ石灰は CO₂、順番は CaCl₂ が先」の 4 点をセットで覚える。",
