    "explanation": "分子式 C₄H₁₀O の異性体（アルコール 4 種とエーテル 3 種）を、反応の違いから決めていく典型問題。正解は①（ア）。\n\n金属ナトリウムと反応して水素を発生するのはヒドロキシ基をもつアルコールなので、A〜D はアルコール、反応しない E はエーテル（ジエチルエーテルなど）である。C₄H₁₀O のアルコールは、1-ブタノール（第一級）、2-ブタノール（第二級）、2-メチル-1-プロパノール（第一級）、2-メチル-2-プロパノール（第三級）の 4 つ。二クロム酸カリウムで酸化されにくい D は、第三級アルコールの 2-メチル-2-プロパノールである。\n\n残る A・B・C のうち、酸化生成物 F がヨードホルム反応陽性であることから、F は CH₃－CO－ の構造をもつケトンで、A は CH₃－CH(OH)－ の構造をもつ 2-ブタノール（第二級）、F は 2-ブタノン（エチルメチルケトン）である。B と C は第一級アルコールで、枝分かれのある 2-メチル-1-プロパノールのほうが分子間の接触面積が小さく沸点が低いので、B ＝ 2-メチル-1-プロパノール、C ＝ 1-ブタノール。第一級アルコールを「完全に酸化」すると、アルデヒドを経てカルボン酸になるので、G ＝ 2-メチルプロパン酸、H ＝ ブタン酸である。\n\n（い）正しい。2-ブタノールの 2 位の炭素には H・OH・CH₃・C₂H₅ の異なる 4 つが結合しており、不斉炭素原子である。\n（ろ）正しい。C は 1-ブタノールで第一級アルコール。\n（は）誤り。D は 2-メチル-2-プロパノールで第三級アルコールである。\n（に）誤り。エーテルはヒドロキシ基をもたず水と水素結合をつくれないので、水に溶けにくい（ジエチルエーテルは水にわずかに溶けるだけで、抽出溶媒として水と分液できる）。\n（ほ）誤り。G・H はカルボン酸であり、還元性をもたないので銀鏡反応を示さない。銀鏡反応を示すのはアルデヒドで、「完全に酸化」されているのでアルデヒドの段階では止まっていない。\n\n「ヨードホルム反応 → CH₃CO－ または CH₃CH(OH)－」「酸化されにくい → 第三級」「枝分かれが多いほど沸点が低い」の 3 つの決め手を順に使う。",
