    "answer": 3,
    "explanation": "等電点と呈色反応からペプチドのアミノ酸①〜⑤を決める。正解はエ。\n\n実験 2（pH 5.1）：等電点が 5.1 より小さい酸性アミノ酸は負に帯電して陽極へ → ③④は Asp・Glu。等電点が 5.1 より大きいものは正に帯電して陰極へ → ①⑤は Lys（9.7）・Tyr（5.7）。等電点がちょうど 5.1 の②は Cys。\n実験 3：カルボキシ基 1 つがメチルエステルになるごとに分子量は 14 増える（–COOH → –COOCH₃）。Asp・Glu はカルボキシ基が 2 つなので ＋28。Glu なら 210 × 175/147 ＝ 250 mg で一致、Asp なら 210 × 161/133 ≒ 254 mg で合わない → ③＝Glu、④＝Asp。\n実験 4：キサントプロテイン反応（濃硝酸で橙黄色）はベンゼン環をもつ Tyr の検出。ペプチド B（①②③）だけが呈色したので ①＝Tyr、⑤＝Lys。\n\nまとめ：①Tyr、②Cys、③Glu、④Asp、⑤Lys。\n\n「陽極へ動く＝等電点が pH より低い酸性アミノ酸」「キサントプロテイン＝ベンゼン環（Tyr）」で絞り、Asp と Glu は分子量の差で区別する。",
